// ---- catalog.js
// USx Parsing: the parsing catalog (0.9.0, user 2026-11-03).
//
// How replies come back in a USx region, and which state formats have been learned. In LA_LEMS, LA is IN STATE:
// LA replies come from the DMV source (BA / B6 person, B1 vehicle, DP photo). Every other state comes back through
// NLETS, and each state has its own format: there is no standard, so each state is learned from real replies.
//
// status per state + message kind:
//   learned  parsed from real replies, with tests
//   partial  seen, but only some variants (more replies wanted)
//   needed   no reply with a record yet
// A state that is not in the catalog at all is "new". The view says so on any reply from a state / format that is
// not learned, so a capture can be sent. The per-state layouts are written up in PARSING_CATALOG.md.
(function (root) {
  'use strict';

  const REGIONS = {
    LA_LEMS: {
      id: 'LA_LEMS', label: 'LA LEMS', home: 'LA', inState: 'DMV', outOfState: 'NLETS',
      // read from the reply text only (never the ConnectCIC envelope, 0.9.8): LA_LEMS in the text, or an LA agency ORI on a line of its own
      detect: (t) => /LA_LEMS/.test(t) || /^\s*LA[A-Z0-9]{7}\s*$/m.test(t)
    }
  };

  // message key -> what it answers
  const MKE_KIND = { DR: 'person', KQ: 'person', RR: 'vehicle', RQ: 'vehicle', BA: 'person', B6: 'person', B1: 'vehicle', B2: 'vehicle', DP: 'photo' };

  const STATES = {
    LA: { name: 'Louisiana', source: 'DMV', formats: {
      person: { status: 'learned', mkes: ['BA', 'B6'], seen: 'BA by OLN (2 replies: 2 credentials + DMV history; a State ID); B6 by name / DOB (1 reply, a State ID)',
        ask: 'LA DMV BA / B6 replies with a CDL, a valid driver licence (class E), several matches by name' },
      vehicle: { status: 'learned', mkes: ['B1', 'B2'], seen: 'B1: 2 real registrations (one with a co-owner) + the test plate; B2: 1 registration (same layout)',
        ask: 'more LA DMV B1 replies: with DMV flags other than CL / SN, a lien holder, a stolen or expired plate' },
      photo: { status: 'partial', mkes: ['DP'], seen: 'the DP header line', ask: 'an LA DLPHOTO reply with the photo' } } },
    CA: { name: 'California', source: 'NLETS', formats: {
      person: { status: 'learned', mkes: ['DR'], seen: 'single record; candidate list (2+ DL#)' },
      vehicle: { status: 'needed', mkes: ['RR'], ask: 'a CA registration (RR) reply' } } },
    FL: { name: 'Florida', source: 'NLETS', formats: {
      person: { status: 'learned', mkes: ['DR'], seen: 'ID card; driver licence (class E)' },
      vehicle: { status: 'needed', mkes: ['RR'], ask: 'an FL registration (RR) reply' } } },
    IL: { name: 'Illinois', source: 'NLETS', formats: {
      person: { status: 'partial', mkes: ['DR'], seen: 'Photo ID only', ask: 'an IL driver licence reply (not a Photo ID)' },
      vehicle: { status: 'needed', mkes: ['RR'], ask: 'an IL registration (RR) reply' } } },
    MA: { name: 'Massachusetts', source: 'NLETS', formats: {
      person: { status: 'learned', mkes: ['DR'], seen: 'driver licence (long-form labels)' },
      vehicle: { status: 'partial', mkes: ['RR'], seen: '1 registration', ask: 'more MA registration (RR) replies' } } },
    MS: { name: 'Mississippi', source: 'NLETS', formats: {
      person: { status: 'partial', mkes: ['DR'], seen: 'CDL class A only', ask: 'an MS non-CDL licence / ID card reply' },
      vehicle: { status: 'needed', mkes: ['RR'], ask: 'an MS registration (RR) reply' } } },
    NY: { name: 'New York', source: 'NLETS', formats: {
      person: { status: 'learned', mkes: ['DR'], seen: 'non-driver ID; NOT ON FILE' },
      vehicle: { status: 'partial', mkes: ['RR'], seen: '1 registration', ask: 'more NY registration (RR) replies' } } }
  };

  const NO_RECORD = /NO RECORDS? FOUND|NOT ON FILE|NO RECORD\b|NO MATCH/i;

  // the region a set of reply texts belongs to (null when none matches)
  function regionOf(texts) {
    const all = [].concat(texts || []).join('\n');
    return Object.values(REGIONS).find((r) => r.detect(all)) || null;
  }

  // one reply: { source: 'DMV' | 'NLETS', state, mke, kind, status, noRecord, ask, label }; null for other sources
  function detect(text, responseType, region) {
    const t = String(text || '');
    const type = String(responseType || '');
    const tracked = (/- Source:\s*(\S+)/i.exec(t) || [])[1] || '';
    const source = /^(DMV|DLPHOTO)$/i.test(type) || /^(DMV|DLPHOTO)$/i.test(tracked) ? 'DMV'
      : /NLETS/i.test(type) || /^NLETS$/i.test(tracked) ? 'NLETS' : null;
    if (!source) return null;
    const mke = ((/- MKE:\s*([A-Z0-9]+)/.exec(t) || [])[1] || (/(^|\n)\s*([A-Z]{2})\.[A-Z]{2}[A-Z0-9]*\b/.exec(t) || [])[2] || '').toUpperCase() || null;
    const reg = region || regionOf(t);
    const state = source === 'NLETS'
      ? ((/- From:\s*([A-Z]{2})/.exec(t) || [])[1] || (/(^|\n)\s*(?:DR|RR|KQ|RQ)\.([A-Z]{2})/.exec(t) || [])[2] || null)
      : (reg ? reg.home : null);
    const kind = (mke && MKE_KIND[mke]) || (/DLPHOTO/i.test(`${type} ${tracked}`) ? 'photo' : null);
    const entry = state ? STATES[state] : null;
    const fmt = entry && kind ? entry.formats[kind] : null;
    const status = !state ? 'unknown' : !entry ? 'new' : fmt ? fmt.status : 'needed';
    const what = { person: 'driver / ID', vehicle: 'registration', photo: 'photo' }[kind] || 'reply';
    return {
      source, state, mke, kind, status,
      noRecord: NO_RECORD.test(t),
      inState: !!(reg && state && state === reg.home),
      ask: fmt && fmt.ask ? fmt.ask : `a ${state || ''} ${source} ${what} reply with a record`.replace(/\s+/g, ' '),
      label: `${state || '?'} ${source}${mke ? ` ${mke}` : ''}`
    };
  }

  const api = { REGIONS, STATES, MKE_KIND, regionOf, detect };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.UsxDexCatalog = api;
})(__usxRoot);

