    caution: [/\bCAUTION\b/, /\bARMED\b/, /\bDANGEROUS\b/, /\bVIOLENT\b/, /\bSUICIDAL\b/, /\bESCAPE RISK\b/, /\bOFFICER SAFETY\b/],
    badStatus: /\b(SUSP(ENDED)?|REVOKED|CANCEL+ED|DISQUALIFIED|DENIED|EXPIRED|INVALID|BARRED|SURRENDERED|STOLEN|UNLICENSED|NOT LICENSED)\b/,
    goodStatus: /\b(VALID|ACTIVE|CURRENT|ELIGIBLE|CLEAR|LICENSED)\b/, // LICENSED: MS DR (0.8.0)
