  // (__usxRoot.UsxDexStore, localStorage). Only settings and dictionary overrides are stored.
  const store = __usxRoot.UsxDexStore || {
    get: (keys) => new Promise((r) => chrome.storage.local.get(keys, r)),
    set: (obj) => new Promise((r) => chrome.storage.local.set(obj, r))
  };
  const extVersion = () => __usxRoot.UsxDexVersion
    || (typeof chrome !== 'undefined' && chrome.runtime && chrome.runtime.getManifest ? chrome.runtime.getManifest().version : null);

